<?php
require_once __DIR__.'/sesion_segura.php';iniciar_sesion_segura();if(empty($_SESSION['usuario'])){header('Location: ./login.php');exit();}require_once './csrf.php';require_once './conexion.php';require_once './validacion_calidad.php';require_once './bitacora_helper.php';require_once './alertify_error.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: control_calidad.php');exit();}validar_token_csrf_post();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1)redirigir_error_alertify('El identificador del control no es válido.');$db=conexion();
try{$db->begin_transaction();$datos=validar_datos_control_calidad($_POST);$operador_id=obtener_operador_calidad($db,(string)$_SESSION['usuario']);$stmt=$db->prepare('SELECT * FROM controles_calidad WHERE id=? FOR UPDATE');$stmt->bind_param('i',$id);$stmt->execute();$actual=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$actual)throw new InvalidArgumentException('El control ya no existe.');$stmt=$db->prepare('SELECT id FROM inventario_derivado WHERE id=? AND cosecha_id=?');if($datos['producto_id']!==null){$stmt->bind_param('ii',$datos['producto_id'],$datos['cosecha_id']);$stmt->execute();$producto=$stmt->get_result()->fetch_assoc();if(!$producto)throw new InvalidArgumentException('El producto debe pertenecer a la cosecha seleccionada.');}$stmt->close();
$stmt=$db->prepare('UPDATE controles_calidad SET cosecha_id=?,inventario_derivado_id=?,tipo_control=?,fecha_control=?,resultado=?,valor=?,unidad=?,observaciones=?,updated_by=? WHERE id=?');$stmt->bind_param('iisssdssii',$datos['cosecha_id'],$datos['producto_id'],$datos['tipo_control'],$datos['fecha_control'],$datos['resultado'],$datos['valor'],$datos['unidad'],$datos['observaciones'],$operador_id,$id);$stmt->execute();$stmt->close();$stmt=$db->prepare('SELECT * FROM controles_calidad WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$nueva=$stmt->get_result()->fetch_assoc();$stmt->close();registrar_evento_bitacora($db,$operador_id,'calidad','Actualizar','controles_calidad',$id,$actual,$nueva);$db->commit();$db->close();header('Location: control_calidad.php?success=update');exit();}catch(Throwable $e){$db->rollback();$db->close();redirigir_excepcion_alertify($e,'No se pudo actualizar el control de calidad.');}
